#!/usr/bin/env python3
"""Clause-library composer.

Reads clause files from a library directory (default: ./clauses). Each file has
YAML front matter between --- lines:

    ---
    id: arbitration
    title: Binding Arbitration
    requires: []          # or a list of "- item" lines: clause ids this needs
    conflicts: []         # or a list of "- item" lines: incompatible ids
    ---
    Clause body text...

Usage:
    python3 compose.py <clause-id> [<clause-id> ...] [--library DIR]

Emits a full contract on stdout. Pulls in transitive requirements, fails on any
conflict within the closure (naming both offending ids), fails on require-cycles
(reporting the cycle path), and orders clauses topologically with alphabetical
id tie-breaking so every requirement precedes its dependents.
"""

from __future__ import annotations

import argparse
import heapq
import sys
from dataclasses import dataclass, field
from pathlib import Path


class ComposeError(Exception):
    """Raised for missing clauses, conflicts, or cycles."""


@dataclass
class Clause:
    id: str
    title: str
    requires: list[str] = field(default_factory=list)
    conflicts: list[str] = field(default_factory=list)
    body: str = ""


def _parse_list_value(raw: str) -> list[str]:
    """Parse an inline YAML-ish list value like '[]' or '[a, b]'."""
    raw = raw.strip()
    if not raw.startswith("[") or not raw.endswith("]"):
        raise ComposeError(f"unsupported list syntax: {raw!r}")
    inner = raw[1:-1].strip()
    if not inner:
        return []
    return [item.strip().strip("'\"") for item in inner.split(",")]


def parse_clause(text: str, source: str) -> Clause:
    """Parse one clause file's front matter + body."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        raise ComposeError(f"{source}: missing front-matter start ('---' on line 1)")
    try:
        end = next(i for i in range(1, len(lines)) if lines[i].strip() == "---")
    except StopIteration:
        raise ComposeError(f"{source}: missing front-matter end ('---')") from None

    fields: dict[str, object] = {}
    current_key: str | None = None
    list_items: list[str] = []
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if line.startswith((" ", "\t")) and current_key is not None:
            # "- item" continuation of the previous key's list.
            if not stripped.startswith("- "):
                raise ComposeError(f"{source}: bad front-matter line: {line!r}")
            list_items.append(stripped[2:].strip().strip("'\""))
            continue
        if ":" not in line:
            raise ComposeError(f"{source}: bad front-matter line: {line!r}")
        key, _, raw = line.partition(":")
        current_key = key.strip()
        raw = raw.strip()
        if raw == "":
            list_items = []
            fields[current_key] = None  # pending; may be filled by "- item" lines
        elif raw == "[]" or (raw.startswith("[") and raw.endswith("]")):
            list_items = []
            fields[current_key] = _parse_list_value(raw)
        else:
            list_items = []
            fields[current_key] = raw.strip("'\"")
        if isinstance(fields.get(current_key), list):
            pass
        if raw == "":
            fields["_pending_" + current_key] = True

    # Attach accumulated "- item" lists to their keys.
    result: dict[str, object] = {}
    pending_key: str | None = None
    items: list[str] = []
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if line[:1] in (" ", "\t"):
            items.append(stripped[2:].strip().strip("'\""))
            continue
        key, _, raw = line.partition(":")
        pending_key = key.strip()
        result[pending_key] = raw.strip()
    final: dict[str, list[str]] = {}
    last_scalar: dict[str, str] = {}
    ordered_keys: list[str] = []
    for line in lines[1:end]:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if line[:1] in (" ", "\t"):
            continue
        key = line.partition(":")[0].strip()
        if key not in ordered_keys:
            ordered_keys.append(key)
    values: dict[str, object] = {}
    i = 0
    parsed_lines = [ln for ln in lines[1:end]
                    if ln.strip() and not ln.strip().startswith("#")]
    idx = 0
    while idx < len(parsed_lines):
        line = parsed_lines[idx]
        if line[:1] in (" ", "\t"):
            raise ComposeError(f"{source}: unexpected indented front-matter line: {line!r}")
        key, _, raw = line.partition(":")
        key = key.strip()
        raw = raw.strip()
        block: list[str] = []
        j = idx + 1
        while j < len(parsed_lines) and parsed_lines[j][:1] in (" ", "\t"):
            entry = parsed_lines[j].strip()
            if not entry.startswith("- "):
                raise ComposeError(f"{source}: bad list entry: {parsed_lines[j]!r}")
            block.append(entry[2:].strip().strip("'\""))
            j += 1
        if raw == "" and block:
            values[key] = block
        elif raw == "":
            values[key] = []
        elif raw.startswith("[") and raw.endswith("]"):
            values[key] = _parse_list_value(raw)
        else:
            values[key] = raw.strip("'\"")
        idx = j

    try:
        cid = values["id"]
        title = values["title"]
    except KeyError as exc:
        raise ComposeError(f"{source}: front matter is missing required field {exc}") from None
    if not isinstance(cid, str) or not cid or not isinstance(title, str) or not title:
        raise ComposeError(f"{source}: 'id' and 'title' must be non-empty strings")

    def as_list(key: str) -> list[str]:
        v = values.get(key, [])
        if not isinstance(v, list):
            raise ComposeError(f"{source}: '{key}' must be a list of clause ids")
        return v

    body = "\n".join(lines[end + 1:]).strip()
    return Clause(id=cid, title=title,
                  requires=as_list("requires"), conflicts=as_list("conflicts"),
                  body=body)


def load_library(library_dir: Path) -> dict[str, Clause]:
    """Load every *.md file in library_dir, keyed by clause id."""
    clauses: dict[str, Clause] = {}
    if not library_dir.is_dir():
        raise ComposeError(f"clause library directory not found: {library_dir}")
    for path in sorted(library_dir.glob("*.md")):
        clause = parse_clause(path.read_text(encoding="utf-8"), source=str(path))
        if clause.id in clauses:
            raise ComposeError(f"duplicate clause id {clause.id!r} "
                               f"(also defined by another file in {library_dir})")
        clauses[clause.id] = clause
    return clauses


def closure(requested: list[str], clauses: dict[str, Clause]) -> set[str]:
    """Expand requested ids to the full set including transitive requirements."""
    seen: set[str] = set()
    stack = list(reversed(requested))
    while stack:
        cid = stack.pop()
        if cid in seen:
            continue
        if cid not in clauses:
            known = ", ".join(sorted(clauses)) or "(none)"
            raise ComposeError(f"unknown clause id {cid!r} (known ids: {known})")
        seen.add(cid)
        stack.extend(reversed(clauses[cid].requires))
    return seen


def check_conflicts(selected: set[str], clauses: dict[str, Clause]) -> None:
    """Raise if any two clauses in the closure conflict."""
    for cid in sorted(selected):
        for other in clauses[cid].conflicts:
            if other in selected:
                raise ComposeError(
                    f"conflict: clause '{cid}' conflicts with clause '{other}'; "
                    f"both are present in the composed contract")


def find_require_cycle(selected: set[str], clauses: dict[str, Clause]) -> list[str]:
    """Return a cycle path ['a', 'b', 'a'] among requires edges, or []."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {cid: WHITE for cid in selected}
    parent: dict[str, str | None] = {}

    def dfs(node: str) -> list[str] | None:
        color[node] = GRAY
        for dep in sorted(clauses[node].requires):  # deterministic exploration
            if dep not in selected:
                continue
            if color[dep] == GRAY:
                path = [dep, node]
                cur = parent.get(node)
                while cur is not None and cur != dep:
                    path.append(cur)
                    cur = parent.get(cur)
                path.append(dep)
                path.reverse()
                return path
            if color[dep] == WHITE:
                parent[dep] = node
                cycle = dfs(dep)
                if cycle:
                    return cycle
        color[node] = BLACK
        return None

    for cid in sorted(selected):
        if color[cid] == WHITE:
            parent[cid] = None
            cycle = dfs(cid)
            if cycle:
                return cycle
    return []


def topo_order(selected: set[str], clauses: dict[str, Clause],
               requested: list[str]) -> list[str]:
    """Kahn's algorithm; requirement before dependent; ties broken alphabetically."""
    indegree = {cid: 0 for cid in selected}
    dependents: dict[str, list[str]] = {cid: [] for cid in selected}
    for cid in selected:
        for req in clauses[cid].requires:
            if req in selected:
                indegree[cid] += 1
                dependents[req].append(cid)

    heap = [cid for cid, deg in indegree.items() if deg == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        cid = heapq.heappop(heap)
        order.append(cid)
        for dep in dependents[cid]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                heapq.heappush(heap, dep)
    if len(order) != len(selected):
        stuck = sorted(set(selected) - set(order))
        raise ComposeError(f"require-cycle detected among: {', '.join(stuck)}")
    return order


def compose(requested: list[str], library_dir: Path) -> str:
    """Return the fully composed contract document, or raise ComposeError."""
    if not requested:
        raise ComposeError("no clause ids requested")
    clauses = load_library(library_dir)
    selected = closure(requested, clauses)
    check_conflicts(selected, clauses)
    cycle = find_require_cycle(selected, clauses)
    if cycle:
        raise ComposeError("require-cycle detected: " + " -> ".join(cycle))
    order = topo_order(selected, clauses, requested)

    parts = ["CONTRACT", "", "This Agreement is entered into as of the date of the",
             "last signature below, between the undersigned parties.", ""]
    parts.append("=" * 72)
    for n, cid in enumerate(order, 1):
        c = clauses[cid]
        parts.append("")
        parts.append(f"{n}. {c.title.upper()}  (clause-id: {c.id})")
        parts.append("-" * 72)
        parts.append("")
        parts.append(c.body)
        parts.append("")
        parts.append("=" * 72)
    parts += ["", "IN WITNESS WHEREOF, the parties have executed this Agreement.", "",
              "Party A: ______________________          Party B: ______________________", "",
              "Composed clause order: " + " -> ".join(order)]
    return "\n".join(parts)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Compose a contract from clause-library ids.")
    parser.add_argument("clauses", nargs="+", metavar="CLAUSE_ID",
                        help="requested clause ids (requirements are pulled in automatically)")
    parser.add_argument("--library", default="clauses", type=Path,
                        help="directory containing clause files (default: ./clauses)")
    args = parser.parse_args(argv)
    try:
        sys.stdout.write(compose(args.clauses, args.library) + "\n")
    except ComposeError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

